import{d as u,C as t,o as c,c as m,j as a,a as o,E as r,a3 as b}from"./chunks/framework.Q4yG9rk_.js";const y=JSON.parse('{"title":"道德经第十一章","description":"从车毂、陶器与居室，理解有形材料和空处怎样共同成就用途。","frontmatter":{"title":"道德经第十一章","description":"从车毂、陶器与居室，理解有形材料和空处怎样共同成就用途。","category":"guide","aliases":["道德经第十一章","老子第十一章","dao de jing chapter 11"],"source":["王弼《道德真经注》卷一"]},"headers":[],"relativePath":"daoism/dao-de-jing/chapter-11.md","filePath":"daoism/dao-de-jing/chapter-11.md","lastUpdated":1794189804000}'),p={name:"daoism/dao-de-jing/chapter-11.md"},_=u({...p,setup(g){const n=[{id:"hub-and-empty-centre",label:"三十辐共一毂",showLabel:!0,sentences:[["三十",{text:"辐",glossary:"fu"},"共一",{text:"毂",glossary:"gu"},"，当其",{text:"无",glossary:"wu"},"，有车之用。"]],note:["【白话】三十根辐条会集在一个车毂上，正因为毂中留有空处，车才有可供使用的作用。这里着眼于毂中容纳车轴的孔，不是说车轮只靠空无就能运行。","【王弼注择要】「毂所以能统三十辐者，无也。」「以其无能受物之故，故能以实统众也。」注把空处能接纳事物与实体结构的统合连在一起。","【读法】先看实体怎样围成可用的空处。三十辐是古代车轮的形制描述，重点不在把三十推演为神秘数字。"]},{id:"vessel-and-room",label:"埏埴以为器",showLabel:!0,sentences:[[{text:"埏埴",glossary:"shanzhi"},"以为器，当其",{text:"无",glossary:"wu"},"，有器之用。"],["凿",{text:"户牖",glossary:"huyou"},"以为室，当其",{text:"无",glossary:"wu"},"，有室之用。"]],note:["【白话】揉和陶土做成器皿，正因为器内有空处，才有容纳东西的用途。开凿门窗、建成居室，正因为留下可出入、居处的空处，才有房屋的用途。","【读法】陶土围成器腹，墙壁围成房间，门窗又使内外通达。材料、边界与空处相互配合，不是把器壁、房屋拆掉才叫重视无。"]},{id:"material-and-use",label:"有之以为利，无之以为用",showLabel:!0,sentences:[["故",{text:"有",glossary:"you"},"之以为",{text:"利",glossary:"li"},"，",{text:"无",glossary:"wu"},"之以为",{text:"用",glossary:"yong"},"。"]],note:["【白话】所以，有形的材料与构造给人便利，未被实体占满的空处使实际用途得以发挥。有与无在同一件器物中共同成就其用。","【王弼注择要】「木、埴、壁所以成三者，而皆以无为用也。」又说「有之所以为利，皆赖无以为用也」。注承认木、土、墙壁成器，也指出它们的利益须由空处落实。","【读法】本章的无先从器物的空处理解，不直接等同第一章未分、未名的无。由具体器物进入更一般的有无关系，要保留这一步语境转换。"]}],s=[{id:"fu",term:"辐",sense:1},{id:"gu",term:"毂",sense:1},{id:"shanzhi",term:"埏埴",sense:1},{id:"huyou",term:"户牖",sense:1},{id:"you",term:"有",sense:2,context:"本章指木、土、墙壁等有形材料与构造。"},{id:"wu",term:"无",sense:2,context:"毂孔、器腹、室内及门窗等可容纳、可通达的空处。"},{id:"li",term:"利",sense:1},{id:"yong",term:"用",sense:1}];return(x,e)=>{const i=t("DaoReadingPrelude"),l=t("DaoTextReading"),d=t("DaoLineGuide"),h=t("DaoKeywordCards");return c(),m("div",null,[e[0]||(e[0]=a("h1",{id:"道德经第十一章",tabindex:"-1"},[o("道德经第十一章 "),a("a",{class:"header-anchor",href:"#道德经第十一章","aria-label":'Permalink to "道德经第十一章"'},"​")],-1)),r(i,{title:"器物的用处，为什么要从空处看？",summary:"车毂、陶器和居室都有可见的材料，也都需要未被材料占满的部分。本章连用三个日常例子，把注意力从做成了什么，转向什么条件使它真正可用。",points:[{label:"先读",text:"三种器物各把空处留在哪里？"},{label:"再辨",text:"实体的便利，怎样通过空处成为用途？"},{label:"后想",text:"我是否只计算添了多少，却忘记能否使用？"}],hint:"竹简模式先通读；经典阅读可展开段释义、点击标记字词查义。"}),e[1]||(e[1]=a("h2",{id:"【原典层】原文与段级释义",tabindex:"-1"},[o("【原典层】原文与段级释义 "),a("a",{class:"header-anchor",href:"#【原典层】原文与段级释义","aria-label":'Permalink to "【原典层】原文与段级释义"'},"​")],-1)),r(l,{sections:n,glossary:s,tone:"ink",density:"comfortable","aria-label":"《道德经》第十一章原文"}),e[2]||(e[2]=a("h2",{id:"【导读层】核心句引读",tabindex:"-1"},[o("【导读层】核心句引读 "),a("a",{class:"header-anchor",href:"#【导读层】核心句引读","aria-label":'Permalink to "【导读层】核心句引读"'},"​")],-1)),r(d,{lines:[{text:"当其无，有车之用。",tone:"转看空处",guide:"同一句式在车、器、室三次出现。重点不是否认看得见的构造，而是发现构造中尚未被占据的部分也承担作用。"},{text:"故有之以为利，无之以为用。",tone:"合看有无",guide:"结句把三例收回有与无的配合。只有材料而没有容纳、通行的余地，成品也可能失去用途；没有合适构造，空处同样未必可用。"}]}),e[3]||(e[3]=a("h2",{id:"【注释层】字词释义",tabindex:"-1"},[o("【注释层】字词释义 "),a("a",{class:"header-anchor",href:"#【注释层】字词释义","aria-label":'Permalink to "【注释层】字词释义"'},"​")],-1)),r(h,{items:s}),e[4]||(e[4]=b('<h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-三个例子为什么都重复「当其无」" tabindex="-1">象：三个例子为什么都重复「当其无」？ <a class="header-anchor" href="#象-三个例子为什么都重复「当其无」" aria-label="Permalink to &quot;象：三个例子为什么都重复「当其无」？&quot;">​</a></h3><p>毂孔可容轴，器腹可盛物，房间与门窗可供居住、出入。可见材料容易吸引注意，空处的作用却容易被忽略。重复使读者在不同器物中看见同一个问题：形体怎样围成条件，让用途发生？</p><h3 id="理-重视无-是否就意味着有不重要" tabindex="-1">理：重视无，是否就意味着有不重要？ <a class="header-anchor" href="#理-重视无-是否就意味着有不重要" aria-label="Permalink to &quot;理：重视无，是否就意味着有不重要？&quot;">​</a></h3><p>王弼明说木、埴、壁成就这三类器物。无的作用依托具体构造，并不取消材料。结句区分利与用，是在说明有形之利怎样得以实现；不宜据此把有判为全无价值，或把一切空缺都说成有益。</p><h3 id="用-怎样判断该留下什么空处" tabindex="-1">用：怎样判断该留下什么空处？ <a class="header-anchor" href="#用-怎样判断该留下什么空处" aria-label="Permalink to &quot;用：怎样判断该留下什么空处？&quot;">​</a></h3><p>先明确要完成的活动，再看需要多少容纳、通达与调整的余地。书架要能取放，日程要能处理意外，协作要有讨论空间。留白应服务实际用途；若必要资源与支持根本不足，应先补足条件。</p><h2 id="【解读层】现代解读与启发" tabindex="-1">【解读层】现代解读与启发 <a class="header-anchor" href="#【解读层】现代解读与启发" aria-label="Permalink to &quot;【解读层】现代解读与启发&quot;">​</a></h2><p><strong>从堆材料转向检查使用。</strong> 做一份资料库，除了收录多少，还要看读者能否找到入口、理解正文、留下自己的思考。这是借器物结构作现代类比，不是将所有组织问题都还原为空间问题。</p><p><strong>让余量有明确职责。</strong> 安排工作时，可以给核对、沟通与返工预留时间，并说明它们对应的需要。余量由用途来判断，不以越空越好，也不把必要劳动隐藏在所谓留白之后。</p><h2 id="【个人记录】我的笔记" tabindex="-1">【个人记录】我的笔记 <a class="header-anchor" href="#【个人记录】我的笔记" aria-label="Permalink to &quot;【个人记录】我的笔记&quot;">​</a></h2><p>留给自己的续读问题：我最近做成的一件东西，真正发挥作用需要哪些不被填满的部分？其中哪些余地被我误当成了浪费？</p><h2 id="校读说明与参考来源" tabindex="-1">校读说明与参考来源 <a class="header-anchor" href="#校读说明与参考来源" aria-label="Permalink to &quot;校读说明与参考来源&quot;">​</a></h2><ul><li>三个例子与结句已对照所据录文核对；本页保留本站句序，按现代标点分段。</li><li>「无」在本章先指器物中可容纳、可通达的空处，字典另立义项，与第一章的未分、未名义区分。</li></ul><p>参考：<a href="https://github.com/kanripo/KR5c0073/blob/b988441bd55861741c850e1dff4a2d4f895daf3d/KR5c0073_001.txt" target="_blank" rel="noreferrer">王弼《道德真经注》卷一 HFL 本电子录文，007a–007b</a>。</p>',15))])}}});export{y as __pageData,_ as default};
